1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import {
4	  ENGINE_VERSION, versionDay, parseVersion, isVersion, isDeclaredVersion, isLegacyVersion,
5	  compareVersions, versionAbove, versionsEqual, nextVersion, versionFromLiteral, VERSION_SOURCE,
6	} from '../engine/version.mjs';
7	
8	test('the day part is the year anchored on 2020, then the month and day', () => {
9	  assert.equal(versionDay('2026-08-20'), 60820);
10	  assert.equal(versionDay(new Date('2026-08-20T23:59:59Z')), 60820);
11	  assert.equal(versionDay('2026-01-01'), 60101);
12	  // The anchor is what keeps the ordering true past 2029, where a last-digit year
13	  // would wrap to 0 and sort a decade of releases underneath.
14	  assert.ok(versionDay('2030-01-01') > versionDay('2029-12-31'));
15	  assert.equal(versionDay('not-a-date'), null);
16	});
17	
18	test('both spellings parse to the same tuple shape, and nothing else does', () => {
19	  assert.deepEqual(parseVersion('60820.1'), { day: 60820, seq: 1 });
20	  assert.deepEqual(parseVersion('60820.12'), { day: 60820, seq: 12 });
21	  assert.deepEqual(parseVersion(6), { day: 6, seq: 0 });
22	
23	  for (const bad of ['60820', '60820.0', '60820.', '.1', '0.1', 'v60820.1', '', null, undefined, -1, 1.5, {}]) {
24	    assert.equal(parseVersion(bad), null, `${JSON.stringify(bad)} is not a version`);
25	    assert.equal(isVersion(bad), false);
26	  }
27	  assert.equal(isLegacyVersion(6), true);
28	  assert.equal(isLegacyVersion('60820.1'), false);
29	});
30	
31	test('zero is the install floor — readable, sorting below everything, never declarable', () => {
32	  assert.deepEqual(parseVersion(0), { day: 0, seq: 0 });
33	  assert.equal(isVersion(0), true, 'a stamp at the install floor says something, and must not read as absence');
34	  assert.equal(isDeclaredVersion(0), false, 'no manifest and no release may write the floor');
35	  assert.ok(compareVersions(0, 1) < 0);
36	  assert.ok(compareVersions(0, '60820.1') < 0);
37	});
38	
39	test('equality refuses to be satisfied by a side it cannot price', () => {
40	  assert.equal(versionsEqual('60820.1', '60820.1'), true);
41	  assert.equal(versionsEqual(6, 6), true);
42	  assert.equal(versionsEqual('60820.1', 6), false);
43	  // compareVersions alone reads an unpriceable side as equal — the trap this closes.
44	  assert.equal(compareVersions('60820.1', undefined), 0);
45	  assert.equal(versionsEqual('60820.1', undefined), false);
46	});
47	
48	test('a legacy integer sorts below every date-anchored version', () => {
49	  assert.ok(compareVersions(6, '60820.1') < 0);
50	  assert.ok(compareVersions(18, '60820.1') < 0);
51	  assert.ok(versionAbove('60820.1', 6));
52	  assert.ok(!versionAbove(6, '60820.1'));
53	});
54	
55	test('the running number orders within a day, and the day orders across days', () => {
56	  // The reason a version is a STRING: as floats, 60820.10 and 60820.1 are one number.
57	  assert.ok(compareVersions('60820.10', '60820.9') > 0);
