1	import { join, dirname } from 'node:path';
2	import { fileURLToPath, pathToFileURL } from 'node:url';
3	import { MIGRATION_FILE, migrationDirs, migrationActive, recordName, flowOf } from '../checks/helpers/active-migrations.mjs';
4	import { RENAMED_PACKS } from '../pack_loader/renamed-packs.mjs';
5	import { SETTINGS_FILE, SETTINGS_FILES, LEGACY_SETTINGS_FILE } from '../settings-file.mjs';
6	import { installedVersions, withInstalledVersions, LEGACY_STAMP_KEY } from '../installed-versions.mjs';
7	import { ENDPOINTS_KEY, LEGACY_ENDPOINTS_KEY } from '../checks/helpers/repo-context.mjs';
8	import { LOCAL_PACK_ROOT, taskDirsWithJson, updateTaskSchedulingFields } from './task-declarations-to-json.mjs';
9	
10	// <corpus>/engine/migrations/ — records are addressed corpus-relative, because they
11	// no longer share one directory with this module: an engine record sits beside it,
12	// a pack's under that pack.
13	const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
14	
15	// Each migration lives in its own folder under the flow that owns it — an engine
16	// record beside this registry, a pack's under that pack — so a record can carry
17	// assets of its own and each flow can ship exactly its own set. The discovery
18	// surface — the roots, the folder listing, the recency predicate, and
19	// `migrationActive` — lives in the vendored engine lib
20	// (engine/checks/helpers/active-migrations.mjs) because pack CHECKS consult it and packs import
21	// only the engine surface (pack-independence); this registry re-exports it so
22	// canon-side callers keep one import home.
23	export { MIGRATION_FILE, migrationActive, recordName };
24	
25	// Structural discovery, like packs/ and skills/: every
26	// <flow>/migrations/<landed-date>-<slug>/migration.mjs is a spec. ALL records
27	// present load — the apply/backfill path is unconditional, and FETCHING decides
28	// relevance: a vendored consumer mount carries only the recent records
29	// (vendoring's recency window), while a dormant project baselining out of a
30	// fresh canon clone sees every record ever landed and applies what it needs.
31	// Each object carries its `dir` — the record's CORPUS-RELATIVE path, which both
32	// names the record and says which flow owns it.
33	export async function loadMigrations() {
34	  const out = [];
35	  for (const d of migrationDirs()) {
36	    const spec = (await import(pathToFileURL(join(corpusRoot, d, MIGRATION_FILE)).href)).default;
37	    const record = { dir: d, ...spec };
38	    // Validated at LOAD, so a retired field cannot reach a flow that would ignore it,
39	    // and a malformed apply-stage declaration cannot reach the flow that acts on it.
40	    assertNoAgenticNote(record);
41	    assertApplyStageDeclaration(record);
42	    out.push(record);
43	  }
44	  return out;
45	}
46	
47	// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
48	// for a canonical target (canonical first, then its legacy aliases). A tolerance
49	// point consults this instead of hardcoding its own LEGACY_* constant, so a
50	// rename is declared once here and every reader picks it up. Unknown targets
51	// resolve to just themselves.
52	export function resolvePath(migrations, canonical) {
53	  for (const m of migrations) {
54	    for (const a of m.aliases ?? []) {
55	      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
56	    }
57	  }
58	  return [canonical];
59	}
60	
61	// Write side — "and rename X -> Y": for each alias whose legacy path still
62	// exists and whose canonical does not, move legacy -> canonical. `exists` and
63	// `move` are injected so the same logic drives a local checkout (sync fs) or a
64	// future API applier (async). Idempotent — a no-op once the rename is done.
65	export async function applyFileAliases(migration, { exists, move }) {
66	  const moved = [];
67	  for (const a of migration.aliases ?? []) {
68	    for (const legacy of a.legacy ?? []) {
69	      if ((await exists(legacy)) && !(await exists(a.canonical))) {
70	        await move(legacy, a.canonical);
71	        moved.push(`${legacy} -> ${a.canonical}`);
72	      }
73	    }
74	  }
75	  return moved;
76	}
77	
78	// Write side — "vendor these pack templates into the repo": for each declared
79	// materialization {template, dest}, copy the canon template to its destination
80	// when the dest is missing or has drifted from the template (idempotent; a
81	// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
82	// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
83	// repo — the source and destination roots differ in a consumer, so they are
84	// distinct injected readers. Gated by the migration's `appliesTo` so it only
85	// touches repos that ship the pipeline (never the canon repo itself).
86	// A materialization whose dest is a WORKFLOW FILE can only be written by a caller that
87	// can get it delivered. The nightly converge pushes with the Action's GITHUB_TOKEN, which
88	// GitHub never lets write under `.github/workflows/`, and the refusal rejects the whole
89	// ref — so writing one into a tree that is about to be pushed by such a caller does not
90	// deliver a workflow, it fails the entire converge and everything else riding it.
91	//
92	// The capable caller announces itself with this variable. The pack update flow sets it
93	// when it can WITHHOLD those paths from its commit and hand them to the apply stage;
94	// anything else — an older vendored worker, a hand-run `node engine/migrations/apply.mjs`, CI —
95	// leaves it unset and the workflow materialization is skipped with a note.
96	//
97	// An ENV HANDSHAKE rather than a probe of the repo on disk, because what matters is what
98	// the RUNNING process can do and the disk cannot answer that: the vendor step earlier in
99	// the same cycle replaces the on-disk worker with the new one while the old code is still
100	// executing.
101	export const WITHHOLD_CAPABLE_ENV = 'CLAUDINITE_CAN_WITHHOLD_WORKFLOWS';
102	const WORKFLOW_DEST = '.github/workflows/';
103	export const callerCanDeliverWorkflows = (env = process.env) => env[WITHHOLD_CAPABLE_ENV] === '1';
104	
105	export async function applyMaterializations(migration, { readTemplate, read, write, env = process.env }) {
106	  if (!migration.materialize?.length) return [];
107	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
108	  const done = [];
109	  for (const { template, dest } of migration.materialize) {
110	    const content = await readTemplate(template);
111	    if (content == null) continue; // template missing (partial mount) — skip, never clobber with nothing
112	    if ((await read(dest)) === content) continue; // already vendored, unchanged
113	    if (dest.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
114	      // Reported rather than silent — a silent skip reads as "already current". A caller
115	      // that can withhold writes it on a later cycle.
116	      done.push(`SKIPPED ${dest} (workflow file; this caller cannot deliver one)`);
117	      continue;
118	    }
119	    await write(dest, content);
120	    done.push(`${dest} <- ${template}`);
121	  }
122	  return done;
123	}
124	
125	// Write side — "rewrite these refs in place": for each declared file, apply its
126	// replacements (only those still matching), writing back when anything changed.
127	// Idempotent — a no-op once nothing matches. Preserves the rest of the file, so
128	// per-repo tweaks the template can't carry (e.g. an uncommented build_env block)
129	// survive. Same `appliesTo` gate.
130	//
131	// A replacement is either LITERAL (`{ from, to }`) or a PATTERN
