50	  // header names the file each run of added lines belongs to.
51	  let file = '';
52	  for (const line of text.split('\n')) {
53	    if (line.startsWith('+++ ')) { file = line.slice(4).replace(/^b\//, ''); continue; }
54	    if (file.endsWith('.test.mjs')) continue;
