1	import { spawnSync } from 'node:child_process';
2	import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
3	import { join, resolve, sep } from 'node:path';
4	import { parseEntries, sessionTranscriptPaths } from './session-transcript.mjs';
5	import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
6	import { canonicalPackVersions } from '../../pack_loader/renamed-packs.mjs';
7	import { SETTINGS_FILE, settingsPath } from '../../settings-file.mjs';
8	import { isVersion } from '../../version.mjs';
9	
10	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
11	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
12	  if (r.status !== 0 && !allowFail) {
13	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
14	  }
15	  return r.status === 0 ? r.stdout : null;
16	}
17	
18	const git = (root, ...args) => sh(root, 'git', args);
19	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
20	
21	// The base branch this repo's work is judged against, in preference order.
22	// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
23	// refs before a context is built at all — one list, so what CI fetches and what a
24	// context resolves can never name different branches.
25	export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];
26	
27	function resolveBaseRef(root) {
28	  for (const ref of BASE_REF_CANDIDATES) {
29	    if (gitTry(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) !== null) return ref;
30	  }
31	  return null;
32	}
33	
34	const FETCH_TIMEOUT_MS = 8000;
35	const FETCH_WINDOW_MS = 5 * 60_000;
36	
37	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
38	// clone freezes it at container-creation time — so every commit the base branch gained
39	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
40	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
41	// rule) report other people's commits as introduced by this change, and `--changed`
42	// widens to files the change never touched. Refreshing the ref once per run is what makes
43	// "the work" mean the work.
44	//
45	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
46	// fetch fails or times out and the run continues against the ref as it stands, exactly as
47	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
48	// no local branch, no index, no working tree, nothing the session could be surprised by.
49	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
50	//
51	// And it runs once per freshness window, not once per run: the Stop hook builds a context
52	// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
53	// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
54	// which ref was refreshed and when; a run inside the window trusts it and skips. The
55	// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
56	// nothing about this base's freshness — and the staleness the window admits is the same
57	// class the fetch's own failure tolerance already accepts, now bounded by the window.
58	function refreshBaseRef(root, ref) {
59	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
60	  const m = /^([^/]+)\/(.+)$/.exec(ref);
61	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
62	  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
63	  const marker = markerRel ? resolve(root, markerRel) : null;
64	  if (marker) {
65	    try {
66	      const last = JSON.parse(readFileSync(marker, 'utf8'));
67	      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
68	    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
69	  }
70	  const [, remote, branch] = m;
71	  const fetched = sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
72	    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
73	  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
74	  if (fetched !== null && marker) {
75	    try { writeFileSync(marker, JSON.stringify({ ref, at: Date.now() })); }
76	    catch { /* an unwritable git dir only costs the next run a fetch */ }
77	  }
78	}
79	
80	function lines(out) {
81	  return (out || '').split('\n').filter(Boolean);
82	}
83	
84	// Files git marks vendored or generated (linguist-vendored / linguist-generated in
85	// .gitattributes) — third-party or machine-written content, not the project's own
86	// code. `buildContext` drops these from the default `ctx.files`, so every check that
87	// reasons about "the project's code" skips them for free: a suppression marker inside
88	// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
89	// link in a vendored doc are none of them the project's decision. `git check-attr`
90	// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
91	// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
92	// check that reasons *about* generated files (generated-merge-driver).
93	function vendoredSet(root, files) {
94	  const set = new Set();
95	  if (!files.length) return set;
96	  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
97	    { allowFail: true, input: files.join('\n') + '\n' });
98	  for (const line of (out || '').split('\n')) {
99	    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
100	    if (m && m[2] === 'set') set.add(m[1]);
101	  }
102	  return set;
103	}
104	
105	// The complete set of top-level settings the settings file may carry. A key
106	// outside this set is a typo or a stale name — a settings error as real as invalid
107	// JSON, caught at load so it can't silently change nothing. `packConfig` is the
108	// legacy home of per-pack parameters — still honored while the fleet migrates to
109	// pack-entry `config` (the converge folds it in), no longer documented. The
110	// `pack-entry-config` baseline migration (engine/migrations/) documents the fold; the
111	// key and the overlay below come out on #1640's window, after which a straggler gets
112	// the unknown-setting error.
113	// `engineVersion` is the engine version this repo's mount holds, written by the
114	// update flows; a pack's installed version sits on that pack's own entry. Both were
115	// a nested `claudinite` block until #1252, alongside an `updated` datetime and a
116	// `ref` — those two held the provenance of the last FULL re-vendor rather than of
117	// this mount, so a member converging nightly read as months stale, and nothing may
118	// judge freshness by them any more because they no longer exist.
119	// `dailyClaudiniteUpdatesRequirePrReview` is the harsh override: true leaves this
120	// repo's daily update PR open for a human. Absent — the normal shape — means it
121	// lands on its own. It is an override rather than a materialized preference
122	// because every member wants the same thing, and the one that doesn't should have
123	// to say so (#1252).
124	// `taskScheduler` is the per-repo maintenance anchor the vendored hourly scheduler
125	// reads (docs/PRINCIPLES.md) — { dailyHour, weeklyDay, monthlyDay },
126	// all UTC. Absence means the documented defaults, so an omitted key is not an
127	// error; a present one is range-validated at load below. Its declaration is also
128	// the per-repo cutover marker during the scheduling rollout (MIGRATION Phase 0.6).
129	// Nothing writes into a member's README any more, so there is no `badges` key here:
130	// a member carrying the stale one gets the unknown-setting error below, and the
131	// wiring converge clears it.

