1	// Fresh-path wiring convergence (docs/PRINCIPLES.md, the primitive absorbed from
2	// #405). The deterministic half of the self-refresh that has nothing to do with the
3	// vendored mount's CONTENT: the repo-specific wiring EVERY Claudinite member carries,
4	// converged idempotently in code so the nightly refresh never needs a model to re-enact
5	// bootstrap's prose.
6	//
7	// DISTRIBUTION WIRING ONLY. What a member needs in order to receive and load pack
8	// content — the settings hooks, the rules index and the CLAUDE.md import that loads it,
9	// the mount's git attributes, the repo's own local pack. Scheduling
10	// wiring is not here: the two workflow files belong to the mechanism that runs them and
11	// are scaffolded at adoption by the tasks pack (#1317), so a member without that pack
12	// converges exactly this and nothing about a queue it does not have.
13	//
14	// One source of truth: bootstrap Part 5 describes this same set for a fresh adoption;
15	// this module is what both bootstrap and the update flows CALL, so the wiring can never
16	// drift between "how a repo is set up" and "how the nightly keeps it set up".
17	//
18	// Operates on a repo working tree at `root` with node:fs directly (like
19	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
20	// repo already converged produces an empty change list.
21	
22	import { existsSync, readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
23	import { join, dirname, relative, sep } from 'node:path';
24	import { pathToFileURL } from 'node:url';
25	import { writeRulesIndex, RULES_INDEX_FILE, RULES_INDEX_IMPORT } from './pack_loader/generate-rules-index.mjs';
26	import { writeSkillsIndex, SKILLS_INDEX_FILE } from './pack_loader/generate-skills-index.mjs';
27	import { LOCAL_PACKS_SUBDIR, LOCAL_DECL_PREFIX, SHARED_SUBDIR } from './pack_loader/pack-registry.mjs';
28	
29	// The mount's two halves as git wants them spelled: '/' separators, and the shared
30	// subtree's own name for a pattern written from inside the mount root. SHARED_SUBDIR
31	// is joined with the platform's separator.
32	const MOUNT_ROOT = dirname(SHARED_SUBDIR).split(sep).join('/');
33	const SHARED_NAME = SHARED_SUBDIR.split(sep).pop();
34	import { settingsPath } from './settings-file.mjs';
35	
36	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
37	// Ensured present without clobbering — a set-union keyed on the command string, so
38	// a repo's own extra hooks and any hand-added entries survive untouched.
39	// The PreToolUse guard watches EVERY tool: an active pack's action declaration
40	// (guardToolCalls) may name any of them, and the guard fast-exits on a call no
41	// declaration names (engine/hooks/pretooluse-command.mjs).
42	export const PRETOOLUSE_MATCHER = '.*';
43	
44	export const REQUIRED_HOOKS = [
45	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
46	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
47	  { event: 'PreToolUse', matcher: PRETOOLUSE_MATCHER, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
48	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
49	  // The two trigger hooks (engine/pack_loader/path-scoped-skills.mjs): an owner
50	  // prompt or a tool result a skill forces itself for gets the load instruction
51	  // injected at that moment. PostToolUse, like PreToolUse, watches every tool.
52	  { event: 'UserPromptSubmit', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/user-prompt-submit-command.mjs' },
53	  { event: 'PostToolUse', matcher: '.*', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/post-tool-use-command.mjs' },
54	];
55	
56	export const SETTINGS_PATH = '.claude/settings.json';
57	export const CLAUDE_MD = 'CLAUDE.md';
58	
59	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
60	// The whole line (and its trailing newline) is removed wherever it appears.
61	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
62	
63	// The project's settings, loaded through the one reader that validates them.
64	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
65	// so the cross-tree import stays a single, reviewable edge.
66	const repoConfig = async (root) => (await import('./checks/helpers/repo-context.mjs')).loadConfig(root);
67	
68	// Ensure the required settings hooks are present (add-if-missing, never clobber).
69	// Returns { added: [labels], error? }. A malformed settings file is reported, never
70	// overwritten (the transactional stance — surface it, don't destroy hand config).
71	export function ensureHooks(root) {
