1	// WHAT THIS MOUNT HOLDS — the engine version a repo has installed, and the version
2	// of each pack it has installed, read out of and written back into its settings
3	// file. One module, because the update flows, the install flow, the vendor writer
4	// and the migration selector all ask the same question of the same file, and four
5	// spellings of "where does the version live" is how a member ends up priced by one
6	// and converged by another.
7	//
8	// WHERE THEY LIVE (#1252). The engine version is the top-level `engineVersion`. A
9	// pack's version is `version` ON THAT PACK'S OWN ENTRY — the one place it cannot
10	// outlive what it prices: the central `claudinite.packVersions` map it replaces was
11	// keyed by a pack id nothing else in the file had to agree with, so a rename left a
12	// version priced against a pack the declaration no longer named.
13	//
14	// THE LEGACY BLOCK IS GONE (#1640). Until then every read here fell back to a
15	// nested `claudinite` block, because a member reached the record that reshapes its
16	// file one converge after the engine that could read the new shape. The convergence
17	// window the `legacy-shape-in-use` advisory opened has passed, and a member still
18	// carrying the block now reads as having no mount at all.
19	// A version is stored data, so an entry written before its pack was renamed still
20	// keys under the old spelling and must PRICE that pack rather than read as
21	// never-installed — absent means the install flow claims it, stamps it at latest,
22	// and runs no migration record in the gap.
23	import { canonicalPackVersions } from './pack_loader/renamed-packs.mjs';
24	// `isVersion`, not `isDeclaredVersion`: the install floor (0) is a real state for a
25	// version a repo HAS — "below everything" — even though nothing may DECLARE it as a
26	// manifest's or a release's own number.
27	import { isVersion } from './version.mjs';
28	
29	// `{ engineVersion, packVersions }` for a parsed settings object — the shape every
30	// caller already passes around as `installed`. Null versions rather than absent
31	// keys: "not installed" is a state of its own, and a caller comparing against a
32	// zero or an empty string would read a fresh mount as ancient.
33	export function installedVersions(raw) {
34	  const engineVersion = isVersion(raw?.engineVersion) ? raw.engineVersion : null;
35	
36	  const packVersions = {};
37	  for (const entry of Array.isArray(raw?.packs) ? raw.packs : []) {
38	    if (entry && typeof entry === 'object' && typeof entry.id === 'string' && isVersion(entry.version)) {
39	      packVersions[entry.id] = entry.version;
40	    }
41	  }
42	  return { engineVersion, packVersions: canonicalPackVersions(packVersions) };
43	}
44	
45	// Has this repo been vendored at all? A mount that has never run stamps neither
46	// number, and every caller that used to ask "is there a stamp" is asking this.
47	export const hasInstalledMount = (raw) => {
48	  const { engineVersion, packVersions } = installedVersions(raw);
49	  return engineVersion !== null || Object.keys(packVersions).length > 0;
50	};
51	
52	// The settings object with these versions recorded: `engineVersion` at the top,
53	// each pack's version on its own entry. Returned rather than written, so the caller
54	// that owns the file owns the write — and so this stays testable without one.
55	//
56	// A version for a pack the declaration does not carry is DROPPED, not appended as
57	// a bare entry: an entry is a declaration that the pack is active, and inventing
58	// one here would activate a pack nobody declared. A pack entry declared as a plain
59	// string is widened to an object so it can hold its version; every other property
60	// and the entry ORDER survive untouched, because this file is one a person reads.
61	export function withInstalledVersions(raw, { engineVersion, packVersions } = {}) {
62	  const next = { ...(raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}) };
63	  if (engineVersion !== undefined && engineVersion !== null) next.engineVersion = engineVersion;
64	
65	  if (packVersions) {
66	    next.packs = (Array.isArray(next.packs) ? next.packs : []).map((entry) => {
67	      const id = typeof entry === 'string' ? entry : entry?.id;
68	      if (typeof id !== 'string' || !Object.hasOwn(packVersions, id)) return entry;
69	      const base = typeof entry === 'string' ? { id: entry } : { ...entry };
70	      // `version` sits directly after `id`, where a reader scanning the list for a
71	      // pack's version finds it beside the name rather than past its config. The
72	      // entry's OWN `version` is destructured out before the spread, not merely
73	      // overwritten by key order: leaving it in `rest` puts the stale number back
74	      // after the new one and freezes every member at the version it already had.
75	      const { id: entryId, version: _prior, ...rest } = base;
76	      return { id: entryId, version: packVersions[id], ...rest };
77	    });
78	  }
79	  return next;
80	}

